using System.Text.Json;using System.Text.RegularExpressions;using ValveKeyValue;using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;
// Tester-only: merge visible wearables into hero, preserve independent visible
// copies for model-rendering particles, keep host locomotion bytes untouched.
internal static class TesterWearableHost {
 private sealed record Donor(string Input,string Target,string Slot,string Hidden,string Visible,string PrivatePath,string? SourceModel=null);
 private sealed record HostEntry(string Host,string Input,string Output,Donor[] Donors);
 private sealed record Particle(string Input,string Output);
 private sealed record Request(HostEntry[] Hosts,Particle[] Particles,Dictionary<string,string>? Meshes,string Report);
 static readonly Regex List=new(@"particle_cfg_list\s*=\s*\[[^\]]*\]",RegexOptions.Singleline);
 static readonly Regex Binding=new("name\\s*=\\s*resource:\\s*\"[^\"]+\\.vpcf\"");
 static bool Bound(Model model){var text=model.Data["m_modelInfo"]["m_keyValueText"].ToString(null);var matches=List.Matches(text);if(matches.Count>1)throw new InvalidDataException("Duplicate particle binding list");return matches.Count==1&&Binding.IsMatch(matches[0].Value);}
 static void CopyModel(Donor d,bool hidden){var bytes=File.ReadAllBytes(d.Input);using var r=new Resource{FileName=d.Input};r.Read(d.Input);var model=r.DataBlock as Model??throw new InvalidDataException("Expected model");var info=model.Data["m_modelInfo"];info["m_keyValueText"]=new KVObject(List.Replace(info["m_keyValueText"].ToString(null),"particle_cfg_list = [ ]"));if(hidden){model.Data["m_refMeshGroupMasks"]=KVObject.Array(model.Data["m_refMeshGroupMasks"].Values.Select(_=>new KVObject(0UL)));model.Data["m_nDefaultMeshGroupMask"]=new KVObject(0UL);}var output=hidden?d.Hidden:d.Visible;using(var s=File.Create(output))Program.SerializePatchedResource(r,bytes,s,true,preserveMetadata:true);using var check=new Resource{FileName=output};check.Read(output);var cm=check.DataBlock as Model??throw new InvalidDataException("Expected written model");if(Bound(cm))throw new InvalidDataException("Duplicate particle launch in wearable copy");if(hidden&&cm.Data["m_nDefaultMeshGroupMask"].ToUInt64(null)!=0)throw new InvalidDataException("Wearable was not hidden");var written=File.ReadAllBytes(output);for(int i=0;i<r.Blocks.Count;i++){var a=r.Blocks[i];var b=check.Blocks[i];if(!ReferenceEquals(a,r.DataBlock)&&!bytes.AsSpan((int)a.Offset,(int)a.Size).SequenceEqual(written.AsSpan((int)b.Offset,(int)b.Size)))throw new InvalidDataException("Wearable runtime block changed: "+a.Type);}}
 public static void Run(string manifest){var q=JsonSerializer.Deserialize<Request>(File.ReadAllText(manifest),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidDataException("Empty tester manifest");if(q.Hosts.Length>32||q.Hosts.Sum(h=>h.Donors.Length)>64||q.Particles.Length>4096)throw new InvalidDataException("Tester manifest too large");var map=new Dictionary<string,string>();var slots=new HashSet<string>();var reports=new List<object>();var notes=new List<string>();
 foreach(var host in q.Hosts){var active=new List<Donor>();foreach(var d in host.Donors){using var resource=new Resource{FileName=d.Input};resource.Read(d.Input);if(resource.DataBlock is not Model model)throw new InvalidDataException("Wearable must be a model");active.Add(d);}
 if(active.Count==0)continue;var merge=host.Output+".merge.json";try{File.WriteAllText(merge,JsonSerializer.Serialize(new{input=host.Input,output=host.Output,hostModel=host.Host,meshes=q.Meshes,donors=active.Select(d=>new{input=d.Input,sourceModel=d.SourceModel,matchBoneCase=true,overrideAttachments=true})}));ModelMerge.Run(merge);}finally{File.Delete(merge);}
 using var original=new Resource{FileName=host.Input};original.Read(host.Input);using var combined=new Resource{FileName=host.Output};combined.Read(host.Output);var originalBones=(original.DataBlock as Model??throw new InvalidDataException("Expected original model")).Skeleton.Bones.Select(b=>b.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);var extras=(combined.DataBlock as Model??throw new InvalidDataException("Expected merged model")).Skeleton.Bones.Where(b=>!originalBones.Contains(b.Name)).Select(b=>b.Name).ToArray();if(extras.Length>0)notes.Add(host.Host+": дополнительные кости сохранены без импорта анимационных слоёв; нужна проверка в игре: "+string.Join(", ",extras));
 foreach(var d in active){CopyModel(d,true);CopyModel(d,false);var key=d.Target.EndsWith("_c")?d.Target[..^2]:d.Target;if(map.TryGetValue(key,out var old)&&old!=d.PrivatePath)throw new InvalidDataException("Conflicting private wearable model");map[key]=d.PrivatePath;slots.Add(d.Slot);}reports.Add(new{host=host.Host,wearables=active.Select(d=>d.Target),extraBones=extras});
 }
 if(map.Count>0&&q.Particles.Length>0){var relocate=manifest+".relocate.json";try{File.WriteAllText(relocate,JsonSerializer.Serialize(new{paths=map,files=q.Particles.Select(p=>new{input=p.Input,output=p.Output})}));ResourceRelocator.Run(relocate);}finally{File.Delete(relocate);}
 foreach(var file in q.Particles){var bytes=File.ReadAllBytes(file.Output);using var r=new Resource{FileName=file.Output};r.Read(file.Output);if(r.DataBlock is not ParticleSystem p)throw new InvalidDataException("Expected particle");bool changed=false;if(p.Data.TryGetValue("m_Renderers",out var renderers))foreach(var renderer in renderers.Values){if(renderer["_class"].ToString(null)!="C_OP_RenderModels"||!renderer.TryGetValue("m_ModelList",out var models)||!models.Values.Any(m=>map.Values.Contains(m["m_model"].ToString(null))))continue;if(renderer.TryGetValue("m_EconSlotName",out var slot)&&slots.Contains(slot.ToString(null))){renderer.Remove("m_modelInput");renderer["m_EconSlotName"]=new KVObject("");changed=true;}}
 if(changed){var temp=file.Output+".patched";using(var s=File.Create(temp))Program.SerializePatchedResource(r,bytes,s,true,preserveMetadata:true);using var check=new Resource{FileName=temp};check.Read(temp);File.Move(temp,file.Output,true);}}
 }
 File.WriteAllText(q.Report,JsonSerializer.Serialize(new{version=2,hosts=reports,warnings=notes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("[OK] Tester full-set base-model hosts: "+reports.Count);}
}
